import{_ as s,o as n,c as e,a3 as p}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"架构总览","description":"","frontmatter":{},"headers":[],"relativePath":"cosmos/basic-app/architecture.md","filePath":"cosmos/basic-app/architecture.md","lastUpdated":1785868852000}'),t={name:"cosmos/basic-app/architecture.md"};function r(i,a,l,c,o,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h1><p>XiHan.BasicApp 是一套基于 <a href="./../framework/index">XiHan.Framework</a> 构建的多租户中后台应用，前后端分离。本页给全景与索引，<strong>细节在四个分册里</strong>：</p><table tabindex="0"><thead><tr><th>分册</th><th>内容</th></tr></thead><tbody><tr><td><a href="./architecture/backend">后端架构</a></td><td>项目分层、模块装配、DDD 三层、DI 约定、菜单事实源、种子 <code>Order</code> 段、框架引用切换</td></tr><tr><td><a href="./architecture/frontend">前端架构</a></td><td>五层结构、启动引导、请求链路时序、依赖归属、环境变量</td></tr><tr><td><a href="./architecture/request-lifecycle">请求生命周期</a></td><td>中间件管道逐段说明、401/403/423 分水岭、UoW 收尾时序</td></tr><tr><td><a href="./architecture/data-model">数据模型</a></td><td>实体基类、主键与审计列、多租户列语义、软删与索引规范、全部数据表清单</td></tr><tr><td><a href="./architecture/caching-async">缓存与异步</a></td><td>缓存条目、精准失效、队列消费、崩溃恢复</td></tr></tbody></table><h2 id="全景" tabindex="-1">全景 <a class="header-anchor" href="#全景" aria-label="Permalink to &quot;全景&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                        XiHan.BasicApp.WebHost                             │</span></span>
<span class="line"><span>│        启动入口 Program.cs + 聚合模块 XiHanBasicAppWebHostModule           │</span></span>
<span class="line"><span>│  [DependsOn] Saas / CodeGeneration / AI / Workflow / Observability / Mcp  │</span></span>
<span class="line"><span>│        健康检查 / MCP Server / Telegram Webhook / /health 端点            │</span></span>
<span class="line"><span>├───────────────┬──────────────────┬───────────────┬───────────────────────┤</span></span>
<span class="line"><span>│ BasicApp.Saas │ BasicApp.        │ BasicApp.AI   │ BasicApp.Workflow     │</span></span>
<span class="line"><span>│ 身份/权限/租户 │  CodeGeneration  │ Provider 库化 │ 流程定义/实例/待办     │</span></span>
<span class="line"><span>│ 消息/文件/日志 │ 数据源/表结构/   │ 知识库 RAG /  │ SqlSugar 持久化存储    │</span></span>
<span class="line"><span>│ 任务/审批/聊天 │ 模板/全栈生成    │ 提示词库      │ 待办站内通知           │</span></span>
<span class="line"><span>├───────────────┴──────────────────┴───────────────┴───────────────────────┤</span></span>
<span class="line"><span>│                        XiHan.BasicApp.Web.Core                            │</span></span>
<span class="line"><span>│      Web 能力聚合：动态 API / Scalar 文档 / SignalR / 网关灰度             │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                          XiHan.BasicApp.Core                              │</span></span>
<span class="line"><span>│  基座抽象：实体/DTO 基类（多租户审计）、查询服务标记接口、聚合框架能力模块    │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                            XiHan.Framework.*                              │</span></span>
<span class="line"><span>│ 认证 / 授权 / 数据(SqlSugar) / 缓存 / 事件总线 / 多租户 / 工作流 / AI / Bot │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>四个业务模块都是<strong>一等模块</strong>，各自独立成项目、经 <code>[DependsOn]</code> 挂到 <code>WebHost</code>，彼此不直接依赖、均以 <code>Saas</code> 为共享基座。新增大功能域时的推荐范式也是<strong>新建独立模块项目，而非往 <code>Saas</code> 里塞切片</strong>。</p><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>XiHan.BasicApp/</span></span>
<span class="line"><span>├── backend/                 # 后端（.NET）</span></span>
<span class="line"><span>│   ├── src/</span></span>
<span class="line"><span>│   │   ├── framework/       #   Core / Web.Core 基座</span></span>
<span class="line"><span>│   │   ├── modules/         #   Saas、CodeGeneration、AI、Workflow 四个业务模块</span></span>
<span class="line"><span>│   │   └── main/            #   WebHost 启动入口</span></span>
<span class="line"><span>│   ├── props/               #   共享 MSBuild 属性（含 framework.props 源码/NuGet 切换）</span></span>
<span class="line"><span>│   ├── scripts/             #   部署与运维脚本</span></span>
<span class="line"><span>│   └── test/                #   测试项目</span></span>
<span class="line"><span>├── frontend/                # 前端（Vue 3 + Naive UI）</span></span>
<span class="line"><span>│   ├── src/                 #   应用装配与业务视图（api / app / router / styles / views）</span></span>
<span class="line"><span>│   └── packages/            #   可复用内核（components / request / router / stores / locales …）</span></span>
<span class="line"><span>└── assets/                  # README 资源</span></span></code></pre></div><h2 id="四条贯穿全局的设计" tabindex="-1">四条贯穿全局的设计 <a class="header-anchor" href="#四条贯穿全局的设计" aria-label="Permalink to &quot;四条贯穿全局的设计&quot;">​</a></h2><p>理解这四条，大部分「为什么这么写」的疑问就解开了。</p><h3 id="一、一切皆模块" tabindex="-1">一、一切皆模块 <a class="header-anchor" href="#一、一切皆模块" aria-label="Permalink to &quot;一、一切皆模块&quot;">​</a></h3><p>能力以 <code>XiHanModule</code> + <code>[DependsOn]</code> 为装配单元，框架按依赖图拓扑排序、逐阶段初始化。加一块能力就是加一行 <code>[DependsOn]</code>，减一块就是删一行。→ <a href="./architecture/backend#模块装配">后端架构</a></p><h3 id="二、后端驱动前端" tabindex="-1">二、后端驱动前端 <a class="header-anchor" href="#二、后端驱动前端" aria-label="Permalink to &quot;二、后端驱动前端&quot;">​</a></h3><p>菜单、路由、组件路径、权限码、国际化键、枚举标签、字段脱敏规则，<strong>事实源全部在后端</strong>。前端只提供视图组件与文案。新增页面的主要工作因此落在后端 <code>PageRegistry</code> 与权限定义上。→ <a href="./architecture/backend#菜单-后端单一事实源">后端架构 · 菜单</a></p><h3 id="三、没有-controller" tabindex="-1">三、没有 Controller <a class="header-anchor" href="#三、没有-controller" aria-label="Permalink to &quot;三、没有 Controller&quot;">​</a></h3><p>应用服务打 <code>[DynamicApi]</code> 即成 REST 接口，路由由方法名推导。这带来两个必须记住的约定：<strong>分页方法要显式标 <code>[HttpPost]</code></strong>、<strong>路由段只由显式 <code>[FromRoute]</code> 参数产生</strong>。→ <a href="./api-guide#动态-api-路由推导规则">接口对接指南</a></p><h3 id="四、读缓存、写失效、耗时异步" tabindex="-1">四、读缓存、写失效、耗时异步 <a class="header-anchor" href="#四、读缓存、写失效、耗时异步" aria-label="Permalink to &quot;四、读缓存、写失效、耗时异步&quot;">​</a></h3><p>热点读走 Redis 分布式缓存，写路径精准失效（且必须排队到事务提交之后）；耗时动作入队由后台服务消费，数据库表是事实源、队列只承载待办工作。→ <a href="./architecture/caching-async">缓存与异步</a></p><h2 id="前后端协作数据流" tabindex="-1">前后端协作数据流 <a class="header-anchor" href="#前后端协作数据流" aria-label="Permalink to &quot;前后端协作数据流&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vue 页面（Schema 驱动列表页）</span></span>
<span class="line"><span>   │  分页走 POST，body = { conditions, page }；附 X-Language / X-Timezone 头</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>动态 API（*AppService / *QueryService，[DynamicApi] 暴露，无 Controller）</span></span>
<span class="line"><span>   │  中间件管道：转发头 → TraceId → 请求文化 → 路由 → CORS → 认证</span></span>
<span class="line"><span>   │                → 租户解析 → 会话闸门(401/423) → 授权(授权快照)</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>应用服务（写侧 [UnitOfWork]） / 查询服务（读侧投影 + 缓存 + FLS 门控）</span></span>
<span class="line"><span>   │  → 领域服务（业务规则） → 仓储（SqlSugar，自动挂租户/软删过滤） → 数据库</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>UoW 收尾：本地事件(提交前) → 提交 → 分布式事件(提交后) → 精准失效缓存 → 队列入队</span></span>
<span class="line"><span>   ▲</span></span>
<span class="line"><span>   └─ 响应统一 ApiResponse 信封；本地化覆盖 Data；时间按 X-Timezone 换算</span></span></code></pre></div><p>逐段解释见 <a href="./architecture/request-lifecycle">请求生命周期</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./architecture/backend">后端架构</a> → <a href="./architecture/request-lifecycle">请求生命周期</a> → <a href="./architecture/data-model">数据模型</a>：后端开发者的推荐顺序</li><li><a href="./architecture/frontend">前端架构</a> → <a href="./frontend">前端开发指南</a>：前端开发者的推荐顺序</li><li><a href="./development">二次开发</a>：动手加功能的完整清单</li><li><a href="./permissions">权限模型</a> / <a href="./multi-tenancy">多租户与版本</a>：两个最容易误解的机制</li></ul>`,23)])])}const b=s(t,[["render",r]]);export{u as __pageData,b as default};
